mapper.select:
select product_barcode from mes_outer_box_bind_record
where outer_box_barcode = #{outerBoxBarcode}
order by bind_sn asc




        and outer_box_barcode = #{outerBoxBarcode}


        and product_barcode = #{productBarcode}


        and bind_by = #{bindBy}


        and bind_time >= #{bindStartTime}


        and bind_time <=#{bindEndTime}


order by bind_time desc, outer_box_barcode asc, bind_sn asc

select distinct outer_box_barcode
from mes_outer_box_bind_record


        and outer_box_barcode = #{outerBoxBarcode}


        and bind_by = #{bindBy}


order by outer_box_barcode desc

select outer_box_barcode as outerBoxBarcode, min(product_barcode) as firstProductBarcode, count(*) as productCount, max(bind_time) as bindTime, min(bind_by) as bindBy from mes_outer_box_bind_record
and outer_box_barcode = #{outerBoxBarcode}
and bind_by = #{bindBy}
group by outer_box_barcode order by bindTime desc
